<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {searchEntries,splitDocument,wordHtmlToQuestionText} from './support-model.js'
import PlatformManager from './PlatformManager.vue'
import PlatformStats from './PlatformStats.vue'
import {COMMON_PLATFORM,platformLabel} from './platforms.js'
import TicketImages from './TicketImages.vue'
import {IMAGE_QUESTION} from '../server/question.js'
import {filterKnowledge} from './knowledge-management.js'
const user=ref(null),booting=ref(true),busy=ref(false),message=ref(''),page=ref('manage');
const username=ref(''),password=ref(''),entries=ref([]),tickets=ref([]),users=ref([]);
const province=ref(''),platform=ref(''),query=ref(''),searched=ref(false),selected=ref(null),reply=ref('');
const admin=computed(()=>user.value?.role==='admin');
const provinces=computed(()=>[...new Set(entries.value.map(e=>e.province))].sort());
const platforms=computed(()=>[...new Set(entries.value.filter(e=>e.province===province.value).map(e=>e.platform))].sort());
const results=computed(()=>searchEntries(entries.value,province.value,platform.value,query.value));
const blank=()=>({province:'',platform:'',question:'',answer:'',keywords:'',source:'',published:false});
const editing=ref(null),manageQuery=ref(''),importProvince=ref(''),importPlatform=ref(''),importText=ref(''),source=ref(''),drafts=ref([]),reviewed=ref(false);
const platformRecords=ref([]),publishOnImport=ref(false);
const resolution=ref(null);
async function savePlatform(value,done){await run(async()=>{await api('platforms',value);await load();done();message.value='平台字典已保存，客服下拉选项已同步'})}
function resolveTicket(t){resolution.value={id:t.id,question:t.question===IMAGE_QUESTION?(t.image_description||''):t.question,imageDescription:t.image_description||'',images:t.images||[],platform:t.platform,answer:t.answer||'',keywords:''};message.value=''}
async function saveResolution(){await run(async()=>{await api('tickets',resolution.value);resolution.value=null;await load();message.value='已处理成功，标准回复已发布到知识库'})}
const passwordForm=ref(null);
function openPassword(name){passwordForm.value={username:name,currentPassword:'',password:'',confirmPassword:''};message.value=''}
async function savePassword(){await run(async()=>{const data=await api('password',passwordForm.value);passwordForm.value=null;if(data.reauthenticate){user.value=null;entries.value=[];users.value=[];message.value='密码已修改，请使用新密码重新登录'}else{message.value='密码已重置，原有登录已失效';await load()}})}
const account=ref({username:'',password:'',role:'staff'});
const managePage=ref(1),managePageSize=ref(10);
const manageStatus=ref('all'),selectedEntryIds=ref([]);
const filtered=computed(()=>filterKnowledge(entries.value,manageQuery.value,manageStatus.value));
const managePageCount=computed(()=>Math.max(1,Math.ceil(filtered.value.length/managePageSize.value)));
const visibleEntries=computed(()=>filtered.value.slice((managePage.value-1)*managePageSize.value,managePage.value*managePageSize.value));
watch([manageQuery,manageStatus,managePageSize],()=>managePage.value=1);
watch([manageQuery,manageStatus,managePageSize,managePage],()=>selectedEntryIds.value=[]);
watch(managePageCount,count=>{managePage.value=Math.min(managePage.value,count)});
function goToManagePage(value){managePage.value=Math.min(managePageCount.value,Math.max(1,value))}
const pageDrafts=computed(()=>visibleEntries.value.filter(e=>!e.published));
const selectedDrafts=computed(()=>pageDrafts.value.filter(e=>selectedEntryIds.value.includes(e.id)));
const allPageDraftsSelected=computed(()=>pageDrafts.value.length>0&&selectedDrafts.value.length===pageDrafts.value.length);
function togglePageDrafts(checked){selectedEntryIds.value=checked?pageDrafts.value.map(e=>e.id):[]}
async function publishSelected(){await run(async()=>{
  const ids=selectedDrafts.value.map(e=>e.id);if(!ids.length)throw new Error('请先勾选需要发布的草稿');
  const result=await api('publishEntries',{ids});selectedEntryIds.value=[];
  message.value='已发布 '+result.published+' 条知识'+(result.skipped?'；'+result.skipped+' 条已发布、已删除或内容不完整，已跳过':'')+'，客服端可立即检索。';
  await load();
})}

watch(province,()=>{platform.value='';clearResult()});watch([platform,query],clearResult);
function clearResult(){searched.value=false;selected.value=null;reply.value=''}
async function api(action,body){const res=await fetch('/api/support?action='+action,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await res.json()}catch{throw new Error('服务器返回异常，请检查部署状态')}if(!res.ok){if(res.status===401)user.value=null;throw new Error(data.error||'请求失败')}return data}
async function run(fn){if(busy.value)return;busy.value=true;message.value='';try{await fn()}catch(e){message.value=e.message}finally{busy.value=false}}
async function load(){const values=await Promise.all([api('entries'),api('tickets'),api('platforms'),...(admin.value?[api('users')]:[])]);entries.value=values[0];tickets.value=values[1];platformRecords.value=values[2];users.value=values[3]||[]}
onMounted(async()=>{try{user.value=(await api('me')).user;if(user.value.role!=='admin'){user.value=null;throw new Error('此入口仅限管理员，请前往客服端登录')}await load()}catch(e){if(e.message!=='请登录')message.value=e.message}finally{booting.value=false}});
async function login(){await run(async()=>{user.value=(await api('login',{username:username.value,password:password.value,adminLogin:true})).user;password.value='';await load()})}
async function logout(){await run(async()=>{await api('logout',{});user.value=null;entries.value=[];tickets.value=[];clearResult()})}
function choose(e){selected.value=e;reply.value=e.answer}
function search(){if(!province.value||!platform.value||!query.value.trim()){message.value='请先选择省份、平台并输入问题';return}message.value='';searched.value=true;selected.value=null;reply.value=''}
async function copy(){try{await navigator.clipboard.writeText(reply.value);message.value='回复已复制'}catch{message.value='复制受浏览器限制，请选中回复文字手动复制'}}
async function saveEntry(){await run(async()=>{await api('entries',editing.value);editing.value=null;await load();message.value='条目已保存'})}
async function deleteEntry(e){if(!confirm('确定删除这条知识吗？建议先导出备份。'))return;await run(async()=>{await api('entries',{id:e.id,delete:true});await load()})}
async function ticket(){await run(async()=>{if(!province.value||!platform.value||!query.value.trim())throw new Error('请先填写平台和问题');await api('tickets',{province:province.value,platform:platform.value,question:query.value});await load();message.value='问题已登记，部门成员可共同查看'})}
async function readWord(event){const file=event.target.files[0];if(!file)return;await run(async()=>{drafts.value=[];importText.value='';reviewed.value=false;publishOnImport.value=false;if(!/\.docx$/i.test(file.name))throw new Error('请在 Word 中另存为 .docx 后导入');if(file.size>10*1024*1024)throw new Error('文档超过 10 MB，请拆分后导入');const mammoth=await import('mammoth/mammoth.browser');const result=await mammoth.convertToHtml({arrayBuffer:await file.arrayBuffer()});const text=wordHtmlToQuestionText(result.value);if(!text.trim())throw new Error('未提取到文字，扫描件或纯图片文档需先转成文字');if(text.length>300000)throw new Error('文字超过 30 万字，请拆分文档');importText.value=text;source.value=file.name;prepare();message.value='已按 Word 标题 / 问答标记整理 '+drafts.value.length+' 条，请逐条核对后保存。'})}
function prepare(){message.value='';reviewed.value=false;drafts.value=splitDocument(importText.value,source.value);if(!drafts.value.length)drafts.value=[{question:'',answer:importText.value,keywords:'',source:source.value,published:false}];if(drafts.value.length>100){drafts.value=[];message.value='超过 100 条，请分批整理'}}
async function importDrafts(){await run(async()=>{
 if(!reviewed.value)throw new Error('请先核对条目');if(!importPlatform.value.trim())throw new Error('请选择知识适用平台');
 const items=[];let skipped=0;
 for(const d of drafts.value){const same=entries.value.find(e=>e.platform===importPlatform.value&&e.question===d.question&&e.answer===d.answer&&e.source===d.source);if(same&&(same.published||!publishOnImport.value)){skipped++;continue}items.push({...d,...(same?{id:same.id}:{}),province:'',platform:importPlatform.value,published:publishOnImport.value})}
 if(items.length)await api('entries',{items});
 const published=publishOnImport.value;drafts.value=[];importText.value='';reviewed.value=false;await load();message.value='已'+(published?'发布':'保存为草稿')+' '+items.length+' 条知识'+(skipped?'，跳过 '+skipped+' 条相同内容':'');page.value='manage';
})}
function backup(){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),entries:entries.value,tickets:tickets.value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='客服知识库备份-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template>
<div v-if="booting" class="loading">正在连接客服工作台…</div>
<div v-else-if="!user" class="login-page"><section class="login-brand"><div class="brand">知答 <span>✦</span></div><small>培训客服知识中心</small><h1>经验有出处，<br>回复有把握。</h1><p>各省平台操作资料，集中维护。<br>让每一位客服都能找到可靠的答案。</p><div class="login-note">部门共享 · 平台隔离 · 审核发布</div></section><form class="login-form" @submit.prevent="login"><small>WELCOME BACK</small><h2>登录管理后台</h2><p>仅限管理员登录</p><label>账号<input v-model="username" autocomplete="username" required maxlength="100"></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required maxlength="256"></label><button class="primary" :disabled="busy">{{busy?'正在登录…':'登录管理后台 →'}}</button><p class="message" role="alert" v-if="message">{{message}}</p><p class="hint">首次使用请用现有部署中配置的管理员账号。<br>没有账号？请联系部门管理员。</p><a href="/">返回客服端 →</a></form></div>
<div v-else class="layout"><aside><div class="brand">知答 <span>✦</span></div><small>培训客服工作台</small><nav><button :class="{active:page==='tickets'}" @click="page='tickets'">◷　待处理问题 <b>{{tickets.filter(t=>!t.resolved).length}}</b></button><template v-if="admin"><div class="nav-label">管理工作区</div><button :class="{active:page==='manage'}" @click="page='manage'">▤　知识管理</button><button :class="{active:page==='import'}" @click="page='import'">↥　Word 导入</button><button :class="{active:page==='platforms'}" @click="page='platforms'">▦　平台字典</button><button :class="{active:page==='stats'}" @click="page='stats'">▥　问题统计</button><button :class="{active:page==='users'}" @click="page='users'">♧　账号管理</button></template></nav><a href="/">返回客服端 →</a><div class="identity"><strong>{{user.username}}</strong><small>{{admin?'管理员':'客服成员'}}</small><button @click="logout" :disabled="busy">退出登录</button></div></aside><main><header><span>内部知识中心 / {{ {search:'查答案',tickets:'待处理问题',manage:'知识管理',import:'Word 导入',users:'账号管理',platforms:'平台字典',stats:'问题统计'}[page] }}</span><button class="quiet" @click="run(load)" :disabled="busy">{{busy?'处理中…':'刷新数据 ↻'}}</button></header><div v-if="message" class="message" role="status">{{message}}<button @click="message=''" aria-label="关闭提示">×</button></div>
<PlatformManager v-if="page==='platforms'&&admin" :platforms="platformRecords" :busy="busy" :message="message" @save="savePlatform"/><PlatformStats v-if="page==='stats'&&admin" :platforms="platformRecords" :tickets="tickets" @resolve="resolveTicket"/>
<section v-if="page==='search'"><div class="heading"><div><small>SUPPORT DESK</small><h1>找到答案，安心回复。</h1><p>按省份与平台检索已审核知识，核对后复制给学员。</p></div><span class="pill">{{entries.filter(e=>e.published).length}} 条已发布知识</span></div><div class="search-box"><div class="row"><label>省份<select v-model="province"><option value="">选择省份</option><option v-for="p in provinces" :key="p">{{p}}</option></select></label><label>平台<select v-model="platform"><option value="">选择培训平台</option><option v-for="p in platforms" :key="p">{{p}}</option></select></label></div><form @submit.prevent="search" class="search-row"><input v-model="query" maxlength="2000" placeholder="输入问题关键词，例如：密码、学时、证书"><button class="primary">检索答案 →</button></form><small>当前为知识库检索，不使用 AI 编造答案。建议使用简短关键词。</small></div><div v-if="!entries.some(e=>e.published)" class="empty"><div>▤</div><h2>知识库等待第一份经验</h2><p>{{admin?'从 Word 导入操作说明，或新增问答。审核发布后，客服就能查询。':'管理员尚未发布知识，请联系管理员添加平台资料。'}}</p><button v-if="admin" class="primary" @click="page='import'">导入 Word 文档</button></div><div v-else-if="!searched" class="empty"><div>⌕</div><h2>先确认平台，再查答案</h2><p>仅显示所选省份与平台的资料，避免操作路径混用。</p></div><div v-else class="result-grid"><section><div class="section-title">{{results.length}} 条相关知识<button class="quiet" :disabled="busy" @click="ticket">登记未解决问题</button></div><p v-if="!results.length" class="empty">未找到匹配答案。请换用简短关键词，或登记问题交由管理员补充。</p><button v-for="e in results" :key="e.id" class="result-card" :class="{chosen:selected?.id===e.id}" @click="choose(e)"><small>{{e.province}} / {{e.platform}}</small><h3>{{e.question}}</h3><p>{{e.answer.slice(0,100)}}</p></button></section><section class="card reply"><h2>回复编辑区</h2><template v-if="selected"><small>依据：{{selected.source||'人工维护'}} · 更新于 {{new Date(selected.updated_at).toLocaleDateString()}}</small><textarea v-model="reply" rows="12"></textarea><button class="primary" :disabled="!reply.trim()" @click="copy">复制回复</button><p class="hint">请核对适用条件后发送。此处编辑不会修改知识库。</p></template><p class="empty" v-else>选择左侧条目，查看完整答案。</p></section></div></section>
<section v-if="page==='manage'&&admin"><div class="heading"><div><h1>知识管理</h1><p>统一维护平台操作说明，草稿仅管理员可见。</p></div><div class="row"><button class="quiet" @click="backup">导出备份</button><button class="primary" @click="editing=blank()">＋ 新增知识</button></div></div><div class="knowledge-filters"><label>关键词<input v-model="manageQuery" placeholder="搜索问题、答案、关键词、平台或来源" aria-label="筛选知识" maxlength="500" :disabled="busy"></label><label>发布状态<select v-model="manageStatus" aria-label="发布状态" :disabled="busy"><option value="all">全部状态</option><option value="draft">草稿</option><option value="published">已发布</option></select></label><button class="quiet" :disabled="busy||(!manageQuery&&manageStatus==='all')" @click="manageQuery='';manageStatus='all'">重置筛选</button></div><p class="hint">输入即筛选；多个关键词用空格分隔，同时匹配。只有已发布知识供客服检索。</p><div class="empty" v-if="!filtered.length">{{entries.length?'没有符合当前条件的知识，请调整关键词或状态。':'暂无知识条目，请新增或导入 Word。'}}</div><div class="knowledge-list-summary"><span>共 {{filtered.length}} 条知识<span v-if="filtered.length"> · 显示第 {{(managePage-1)*managePageSize+1}}–{{Math.min(managePage*managePageSize,filtered.length)}} 条</span></span><label>每页条数<select v-model.number="managePageSize" aria-label="每页条数" :disabled="busy"><option :value="10">10 条</option><option :value="20">20 条</option><option :value="50">50 条</option></select></label></div><div class="knowledge-bulk" v-if="filtered.length"><label class="check"><input type="checkbox" :checked="allPageDraftsSelected" :indeterminate="selectedDrafts.length>0&&!allPageDraftsSelected" :disabled="busy||!pageDrafts.length" @change="togglePageDrafts($event.target.checked)">全选本页草稿</label><span>已选 {{selectedDrafts.length}} 条</span><button class="primary" :disabled="busy||!selectedDrafts.length" @click="publishSelected">{{busy?'处理中…':'批量发布（'+selectedDrafts.length+'）'}}</button><small>请核对内容后发布；翻页或筛选会清空勾选。</small></div><article class="card knowledge-item" v-for="e in visibleEntries" :key="e.id"><div class="knowledge-content"><label class="check knowledge-select" v-if="!e.published"><input type="checkbox" v-model="selectedEntryIds" :value="e.id" :disabled="busy" :aria-label="'选择草稿：'+e.question">选择此草稿</label><small>{{e.province}} / {{e.platform}} · {{e.published?'已发布':'草稿'}}</small><h3>{{e.question}}</h3><p>{{e.answer.slice(0,160)}}</p><small>来源：{{e.source||'人工维护'}}</small></div><div class="row"><button class="quiet" @click="editing={...e}" :disabled="busy">{{e.published?'编辑':'编辑 / 发布'}}</button><button class="danger" :disabled="busy" @click="deleteEntry(e)">删除</button></div></article><nav class="knowledge-pagination" aria-label="知识管理分页"><button class="quiet" :disabled="busy||managePage===1" @click="goToManagePage(1)">首页</button><button class="quiet" :disabled="busy||managePage===1" @click="goToManagePage(managePage-1)">上一页</button><span aria-live="polite">第 {{managePage}} / {{managePageCount}} 页</span><button class="quiet" :disabled="busy||managePage>=managePageCount" @click="goToManagePage(managePage+1)">下一页</button><button class="quiet" :disabled="busy||managePage>=managePageCount" @click="goToManagePage(managePageCount)">末页</button></nav></section>
<section v-if="page==='import'&&admin"><h1>从 Word 导入知识</h1><p>识别 Word 标题 → 自动拆分问答 → 核对并保存 / 发布</p><div class="card"><div class="row"><label>知识适用平台<select v-model="importPlatform" @change="reviewed=false"><option value="">请选择平台或通用知识</option><option v-for="p in platformRecords.filter(p=>p.active)" :key="p.id" :value="p.name">{{platformLabel(p.name)}}</option></select></label></div><label class="upload">选择 Word 文档<input type="file" accept=".docx" @change="readWord" :disabled="busy"></label><p class="hint">支持 .docx，最大 10 MB。按 Word 标题或问答标记拆分；仅导入文字，图片不识别，表格与编号需核对。旧版 .doc 请先另存为 .docx。</p><label>资料来源<input v-model="source" maxlength="1000"></label><label>提取内容 / 粘贴问答文本<textarea v-model="importText" rows="12" placeholder="可上传 Word 自动提取，也可粘贴：问题：… 换行 答案：…" @input="drafts=[];reviewed=false"></textarea></label><p class="hint">支持 Word 问题标题或“问题：… / 答案：…”标记；每个标题下的处理步骤保留在同一条答案中。无法识别时请手工补充。</p><button class="primary" @click="prepare">整理问答草稿</button></div><div class="card" v-for="(d,i) in drafts" :key="i"><div class="section-title">条目 {{i+1}}<button class="quiet" @click="drafts.splice(i,1);reviewed=false">移除此条</button></div><label>学员问题 / 检索标题<input v-model="d.question" maxlength="1000" @input="reviewed=false"></label><label>检索关键词（用逗号分隔）<input v-model="d.keywords" maxlength="2000"></label><label>标准答案<textarea v-model="d.answer" rows="6" maxlength="30000" @input="reviewed=false"></textarea></label></div><div v-if="drafts.length" class="card"><label class="check"><input type="checkbox" v-model="reviewed">我已核对提取的文字及平台归属</label><label class="check"><input type="checkbox" v-model="publishOnImport">核对后直接发布，客服可立即检索</label><button class="primary" :disabled="busy||!reviewed" @click="importDrafts">{{publishOnImport?'发布':'保存'}} {{drafts.length}} 条{{publishOnImport?'知识':'草稿'}}</button></div></section>
<section v-if="page==='tickets'"><h1>待处理问题</h1><p>每次生成回复都会自动记录。填写最终回复并处理成功后，自动发布到对应平台的知识库。</p><div class="empty" v-if="!tickets.length">暂无问题记录。</div><article v-for="t in tickets" :key="t.id" class="card"><small>{{t.platform||'待确认平台'}} · {{t.resolved?'处理成功':'待处理'}}</small><h3>{{t.question}}</h3><TicketImages :images="t.images||[]"/><div v-if="t.image_description" class="recognition"><strong>AI 截图识别（待核对）</strong><p>{{t.image_description}}</p></div><p v-if="t.answer">最终回复：{{t.answer}}</p><small>{{t.author}} · {{new Date(t.created_at).toLocaleString()}}</small><button v-if="admin" class="quiet" :disabled="busy" @click="resolveTicket(t)">{{t.resolved?'修改回复并同步知识库':'处理问题'}}</button></article></section>
<section v-if="page==='users'&&admin"><h1>账号管理</h1><button class="quiet" @click="openPassword(user.username)">修改我的密码</button><p>客服可检索已发布知识和登记问题；知识维护由管理员负责。</p><form class="card" @submit.prevent="run(async()=>{await api('users',account);account={username:'',password:'',role:'staff'};await load();message='账号已保存'})"><div class="row"><label>登录账号<input v-model="account.username" required maxlength="100" autocomplete="off"></label><label>初始密码 / 重置密码<input v-model="account.password" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label></div><label>账号角色<select v-model="account.role"><option value="staff">客服</option><option value="admin">管理员</option></select></label><p class="hint">至少 12 位。同名账号会重置密码并启用，请通过部门内部渠道告知本人。</p><button class="primary" :disabled="busy">创建 / 重置账号</button></form><article class="card section-title" v-for="u in users" :key="u.username"><button class="quiet" :disabled="busy" @click="openPassword(u.username)">重置密码</button><span>{{u.username}} · {{u.role==='admin'?'管理员':'客服'}} · {{u.active?'启用':'停用'}}</span><button class="quiet" :disabled="busy" @click="run(async()=>{await api('users',{username:u.username,active:!u.active});await load()})">{{u.active?'停用':'启用'}}</button></article></section>
<footer>知答 · 部门共享知识库 <span>先核对，再发送</span></footer></main></div>
<div class="modal" v-if="editing"><form class="card modal-content" @submit.prevent="saveEntry"><div class="section-title"><h2>{{editing.id?'编辑知识':'新增知识'}}</h2><button type="button" class="quiet" @click="editing=null">关闭</button></div><div class="row"><label>知识适用平台<select v-model="editing.platform" required><option value="">请选择</option><option v-for="p in platformRecords" :key="p.id" :value="p.name">{{platformLabel(p.name)}}{{p.active?'':'（停用）'}}</option></select></label></div><label>问题<input v-model="editing.question" required maxlength="1000"></label><label>关键词（逗号分隔）<input v-model="editing.keywords" maxlength="2000"></label><label>标准答案<textarea v-model="editing.answer" required rows="7" maxlength="30000"></textarea></label><label>资料来源<input v-model="editing.source" maxlength="1000"></label><label class="check"><input type="checkbox" v-model="editing.published">内容已审核，发布给客服使用</label><p v-if="message" role="alert">{{message}}</p><button class="primary" :disabled="busy">保存知识</button></form></div>
<div class="modal" v-if="passwordForm"><form class="card modal-content" @submit.prevent="savePassword"><h2>{{passwordForm.username===user?.username?'修改我的密码':'重置账号密码'}}</h2><p>账号：{{passwordForm.username}}。保存后，该账号原有登录将失效。</p><label v-if="passwordForm.username===user?.username">当前密码<input v-model="passwordForm.currentPassword" type="password" required maxlength="256" autocomplete="current-password"></label><label>新密码<input v-model="passwordForm.password" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><label>再次输入新密码<input v-model="passwordForm.confirmPassword" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><p role="alert" v-if="message">{{message}}</p><div class="row"><button class="primary" :disabled="busy">确认保存</button><button type="button" class="quiet" :disabled="busy" @click="passwordForm=null">取消</button></div></form></div>
<div class="modal" v-if="resolution"><form class="card modal-content" @submit.prevent="saveResolution"><h2>处理成功并入库</h2><TicketImages :images="resolution.images"/><div v-if="resolution.imageDescription" class="recognition"><strong>AI 截图识别（待核对）</strong><p>{{resolution.imageDescription}}</p></div><label>问题描述<input v-model="resolution.question" required maxlength="2000" placeholder="根据截图填写可检索的问题描述"></label><label>确认所属平台<select v-model="resolution.platform" required><option value="">请选择</option><option v-for="p in platformRecords" :key="p.id" :value="p.name">{{platformLabel(p.name)}}{{p.active?'':'（停用）'}}</option></select></label><label>最终回复<textarea v-model="resolution.answer" required rows="8" maxlength="30000" placeholder="填写经确认、可直接发送给学员的回复"></textarea></label><label>检索关键词<input v-model="resolution.keywords" maxlength="2000" placeholder="用逗号分隔，例如：学时,进度"></label><p class="hint">保存后自动发布到当前平台知识库；再次修改会更新同一条知识，不重复新增。</p><p role="alert" v-if="message">{{message}}</p><div class="row"><button class="primary" :disabled="busy">处理成功并入库</button><button type="button" class="quiet" :disabled="busy" @click="resolution=null">取消</button></div></form></div>
</template>
